package com.ejemplo.msb.controller;import com.ejemplo.msb.dto.*;import com.ejemplo.msb.service.EntityBService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController@RequestMapping("/api/entity-b")public class EntityBController{private final EntityBService service;public EntityBController(EntityBService s){service=s;}@GetMapping public List<EntityBDtoList> list(){return service.findAll();}@GetMapping("/{id}")public ResponseEntity<EntityBDtoList> get(@PathVariable Long id){return service.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());}@PostMapping public ResponseEntity<EntityBDtoList> create(@Valid@RequestBody EntityBDto dto){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(dto));}@PutMapping("/{id}")public ResponseEntity<EntityBDtoList> update(@PathVariable Long id,@Valid@RequestBody EntityBDto dto){return service.update(id,dto).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());}@GetMapping("/uses-division/{divisionId}")public boolean usesDivision(@PathVariable Long divisionId){return service.usesDivision(divisionId);}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@PathVariable Long id){return service.delete(id)?ResponseEntity.noContent().build():ResponseEntity.notFound().build();}}
